const sortByLabel = (arr) => arr.sort((a, b) => a.label.localeCompare(b.label));

const buildAddressLabel = (site = {}) =>
	site?.site_address ||
	[site?.street1, site?.street2, site?.city, site?.state, site?.country, site?.zip].filter(Boolean).join(", ");

// Utility: Sort by customer name, then label
const sortByCustomerThenLabel = (arr) =>
	arr.sort((a, b) => {
		const aCustomer = a?.customer || "";
		const bCustomer = b?.customer || "";
		if (aCustomer !== bCustomer) {
			return aCustomer.localeCompare(bCustomer);
		}
		const aLabel = a?.label || "";
		const bLabel = b?.label || "";
		return aLabel.localeCompare(bLabel);
	});

// Utility: Convert users to dropdown options
const getUserOptions = (users) =>
	(users || []).map((user) => ({
		org_id: user?.org_id ?? null,
		customer: user?.organization?.name || "",
		email: (user?.emails && user.emails[0]?.address) ? user.emails[0].address : "",
		value: user?.id,
		label: user?.name || "",
	}));

// Map priority string to numeric value
const getPriorityValue = (priorityString) => {
	const priorityMap = {
		'Low': 1,
		'Normal': 2,
		'High': 3,
		'Emergency': 4
	};
	return priorityMap[priorityString] || 2; // Default to Normal (2) if not found
};

const getDefaultAppointmentTimeZone = (override) => {
	let tz = override || getUserTimezone();
	if (!tz || tz === "system_default") tz = getSystemTimezone();
	return tz || "UTC";
};

const TERMINAL_TICKET_STATES = new Set(["closed", "resolved", "archived"]);

const isTerminalTicketState = (status) => {
	const normalized = String(status || "")
		.toLowerCase()
		.replace(/\s+/g, "_")
		.replace(/-/g, "_");
	return TERMINAL_TICKET_STATES.has(normalized);
};

