	// Helper function to convert date to booking timezone for display
	// Takes a moment object (which may be in any timezone) and converts it to the booking timezone
	const fromUtcToBookingTimezone = (dateTimeMoment, bookingTimezone) => {
		if (!dateTimeMoment || !bookingTimezone) {
			console.error("Missing dateTime or bookingTimezone:", dateTimeMoment, bookingTimezone);
			return moment();
		}

		// If dateTimeMoment is already a moment object, use it
		const m = moment.isMoment(dateTimeMoment) ? dateTimeMoment : moment(dateTimeMoment);

		if (!m.isValid()) {
			console.error("Invalid dateTime:", dateTimeMoment);
			return moment();
		}

		// Convert the moment to UTC first (to get the same instant in time)
		// Then convert from UTC to the booking timezone
		const utcMoment = m.utc();
		const momentInBookingTimezone = utcMoment.tz(bookingTimezone);

		console.log("Converting to booking timezone:", {
			original: m.format(),
			originalTimezone: m.tz ? m.tz() : 'local',
			utc: utcMoment.format(),
			bookingTimezone: bookingTimezone,
			result: momentInBookingTimezone.format()
		});

		return momentInBookingTimezone;
	};

