			requiredFields.push("staff_assigned");
		}

		const errors = {};
		requiredFields.forEach((field) => {
			const rawValue = formData[field];
			const value = sanitizeForRequired(field, rawValue);
			if (
				value === null ||
				value === "" ||
				(typeof value === "string" && !value.trim()) ||
				(moment.isMoment(value) && !value.isValid())
			) {
				errors[field] = true;
			}
		});

		// If user selected "Other" location, validate address fields conditionally
		if (formData.location === "other") {
			const isBlank = (v) => (typeof v === "string" ? v.trim().length === 0 : v === null || v === undefined || v === "");
			if (isBlank(formData.country)) errors.country = true;
			if (isBlank(formData.street1)) errors.street1 = true;
			if (isBlank(formData.zip)) errors.zip = true;
			const requireState = Boolean(formData.country && formData._hasStatesOptions === true);
			const requireCity = Boolean(formData.state && formData._hasCitiesOptions === true);
			if (requireState && isBlank(formData.state)) errors.state = true;
			if (requireCity && isBlank(formData.city)) errors.city = true;
		}

		if (Object.keys(errors).length > 0) {
			setFormErrors(errors);
			setError("Please fill all the required fields.");
			return false;
		}
		setFormErrors({});
		setError(null);
		return true;
	};

	const handleNext = () => {
		if (activeStep === 0) {
			const requiredFields = ["title", "notes", "start_date", "end_date", "timeZone"];
			const newErrors = {};

			requiredFields.forEach((field) => {
				const rawValue = formData[field];
				const value = sanitizeForRequired(field, rawValue);
				if (typeof value === "string") {
					if (!value.trim()) newErrors[field] = true;
				} else if (value === undefined || value === null) {
					newErrors[field] = true;
				} else if (value === "") {
					newErrors[field] = true;
				}
			});

			const updatedErrors = {};
			requiredFields.forEach((field) => {
				updatedErrors[field] = !!newErrors[field]; // true if error, false otherwise
			});
			setFormErrors(updatedErrors);

			if (Object.keys(newErrors).length > 0) {
				setError("Please fill all the required fields.");
				return;
			} else {
				setError(null);
			}
		}
		if (activeStep === 1 && hasChecklistStep) {
			if (!validateTicketStep()) return;
		}
		setActiveStep((prev) => Math.min(prev + 1, steps.length - 1));
	};
