	const toUtcFromSelectedTimezone = (dateTimeMoment, timezone) => {
		if (!dateTimeMoment || !timezone) {
			console.error("Missing dateTime or timezone:", dateTimeMoment, timezone);
			return null;
		}

		// If dateTimeMoment is already a moment object, extract its date/time components
		// and create a new moment in the selected timezone
		const m = moment.isMoment(dateTimeMoment) ? dateTimeMoment : moment(dateTimeMoment);

		if (!m.isValid()) {
			console.error("Invalid dateTime:", dateTimeMoment);
			return null;
		}

		// Get the date/time components from the moment object
		const year = m.year();
		const month = m.month(); // 0-11
		const date = m.date();
		const hour = m.hour();
		const minute = m.minute();
		const second = m.second();

		// Create a new moment in the selected timezone with these components
		// This treats the selected date/time as if it's in the selected timezone
		const momentInTimezone = moment.tz({
			year, month, date, hour, minute, second
		}, timezone);

		// Convert to UTC
		const utcString = momentInTimezone.utc().format();

		console.log("Converting to UTC:", {
			original: m.format(),
			timezone: timezone,
			interpretedInTimezone: momentInTimezone.format(),
			utc: utcString
		});

		return utcString;
	};

