		// Determine entity and action for alerts
		const entity = `${getNamespace("appointment", { capitalize: true, plural: false })}`;
		const action = isEditing ? "update" : "create";

		// Validate checklist step (if present)
		if (activeStep === steps.length - 1 && hasChecklistStep) {
			if (!validateCustomForms()) {
				AlertService.logicFailure(action, entity, "Please resolve checklist errors before submitting.");
