		}

		console.log(formData);
		const selectedTicketDeptId = (() => {
			if (formData.ticket && formData.ticket !== "new") {
				const t = (tickets || []).find(
					(ticket) => String(ticket.ticket_id || ticket.id) === String(formData.ticket)
				);
				return t?.dept_id || t?.department || null;
			}
			if (formData.department) return formData.department;
			return null;
		})();

		const selectedTicket = formData.ticket && formData.ticket !== "new"
			? (tickets || []).find((t) => String(t?.ticket_id || t?.id) === String(formData.ticket))
			: null;
		const staffId =
			user?.staff?.staff_id ||
			user?.staff_id ||
			user?.account?.id ||
			user?.id;
		const isSelectedTicketParticipant =
			selectedTicket &&
			staffId &&
			([
				selectedTicket?.assigned_staff_id ?? selectedTicket?.ticket_assignee?.staff_id,
				selectedTicket?.accountable_staff_id ?? selectedTicket?.ticket_accountable?.staff_id,
				selectedTicket?.created_by_staff_id ?? selectedTicket?.ticket_creator_staff?.staff_id,
			].some((id) => id != null && String(id) === String(staffId)) ||
				(selectedTicket?.ticket_collaborators || []).some(
					(c) => String(c?.staff_id ?? c?.collaborator_staff?.staff_id) === String(staffId)
				));

		if (
			isAgent &&
			selectedTicketDeptId &&
			!(
				hasPermsV2("appointment_management.appointment.create", selectedTicketDeptId) ||
				((ticketAccessOverride || isSelectedTicketParticipant) && hasPermsV2("appointment_management.appointment.create"))
			)
		) {
			AlertService.logicFailure(
				action,
				entity,
				`You do not have permission to create ${getNamespace("appointment", {
					capitalize: false,
					plural: true,
				})} for this department.`
			);
			return;
		}
		const requiredFields =
			formData.ticket && formData.ticket !== "new"
				? ["title", "notes", "start_date", "end_date", "timeZone", "location"]
				: isAgent
					? ["customer", "user", "location", "staff_accountable", "department", "service_type"]
					: ["customer", "location", "service_type"]; // Exclude department for non-agents
		if (userMode === "agent") {
			requiredFields.push("staff_assigned");
		}
		const errors = {};
		requiredFields.forEach((field) => {
			const rawValue = formData[field];
			const value = sanitizeForRequired(field, rawValue);
			if (
				value === null ||
				value === "" ||
				(typeof value === "string" && !value.trim()) ||
				(moment.isMoment(value) && !value.isValid())
			) {
				errors[field] = true;
			}
		});

		// If user selected "Other" location, validate address fields conditionally
		if (formData.location === "other") {
			const isBlank = (v) => (typeof v === "string" ? v.trim().length === 0 : v === null || v === undefined || v === "");
			// Always require country, street1, and zip for a new location
			if (isBlank(formData.country)) errors.country = true;
			if (isBlank(formData.street1)) errors.street1 = true;
			if (isBlank(formData.zip)) errors.zip = true;
			// Conditionally require state and city based on options emitted by AddressForm
			const requireState = Boolean(formData.country && formData._hasStatesOptions === true);
			const requireCity = Boolean(formData.state && formData._hasCitiesOptions === true);
			if (requireState && isBlank(formData.state)) errors.state = true;
