				create_reports: hasCreateNewReport ? [{ report_flow: formData.report_flow || "customer_visibility", job_type: formData.job_type || "TM" }] : [],
				createTicket: formData.ticket === "new",
				ticket_id: formData.ticket,
				job_id: null,
				job_type: hasCreateNewReport ? formData.job_type : null,
				service_report_pack_id: formData.service_report_pack_id || null,
				attach_report_ids: selectedServiceReports
					? selectedServiceReports
							.filter((v) => typeof v === "string" && v.startsWith("report:"))
							.map((v) => Number(String(v).split(":")[1]))
							.filter((n) => Number.isFinite(n))
					: [],
				selected_pack_template_ids: selectedServiceReports
					? selectedServiceReports
							.filter((v) => typeof v === "string" && v.startsWith("tpl:"))
							.map((v) => Number(String(v).split(":")[1]))
							.filter((n) => Number.isFinite(n))
					: [],
				service_type: formData.service_type,
				priority: formData.priority,
				due_date: formData.due_date,
				equipment_id: formData.equipment === "" ? null : formData.equipment,
			};
			// Exclude department_id for non-agents
			if (isAgent) {
				req_body.department_id = formData.department;
			}

			// Build checklist payload (same rule/structure as CreateTicketForm)
			if (hasChecklistStep && customFormsForServiceType.length > 0) {
				const selectedForm = customFormsForServiceType.find((f) => String(f.id) === String(selectedChecklistId)) || customFormsForServiceType[0];
				const fieldsSource = selectedForm?.fields || selectedForm?.schema?.fields || [];

				const fieldsWithValue = fieldsSource.map((field) => {
					const rawVal = (customFormValues && customFormValues[field.name] !== undefined)
						? customFormValues[field.name]
						: (field.value !== undefined ? field.value : "");

					if (field.type === "attachment") {
						const attType = rawVal?.attachmentType || "na";
						let fileName = null;
						if (attType === "custom_form_files") {
							const f = rawVal?.file;
							if (Array.isArray(f) && f.length > 0) {
								const first = f[0];
								fileName = typeof first === "string" ? first : (first?.name || first?.filename || null);
							} else if (f && typeof f === "object") {
								fileName = f.name || f.filename || null;
							} else if (typeof f === "string") {
								fileName = f;
							}
						}
						return {
							...field,
							value: {
								attachmentType: attType === "custom_form_files" ? "custom_form_files" : (attType === "url" ? "url" : "na"),
								attachmentUrl: attType === "url" ? (rawVal?.attachmentUrl || null) : null,
								file: attType === "custom_form_files" ? fileName : null,
								rel: field.name,
							},
						};
					}

					if (field.type === "file_upload") {
						const v = rawVal;
						let fileName = null;
						if (Array.isArray(v) && v.length > 0) {
							const first = v[0];
							fileName = typeof first === "string" ? first : (first?.name || first?.filename || null);
						} else if (v && typeof v === "object") {
							fileName = v.name || v.filename || null;
						} else if (typeof v === "string") {
							fileName = v;
						}
						return {
							...field,
							value: {
								attachmentType: "custom_form_files",
								file: fileName,
								rel: field.name,
							},
						};
					}

					if (field.type === "inspection") {
						const v = rawVal || {};
						const filesRaw = v.files || v.file || [];
						let fileNames = [];
						if (Array.isArray(filesRaw)) {
							fileNames = filesRaw.map((f) => {
								if (!f) return null;
								if (typeof f === "string") return f;
								if (typeof f === "object") return f.name || f.filename || null;
								return null;
							}).filter(Boolean);
						} else if (filesRaw && typeof filesRaw === "object") {
							const name = filesRaw.name || filesRaw.filename || null;
							if (name) fileNames = [name];
						}
						return {
							...field,
							value: {
								inspection: v.inspection ?? null,
								notes: v.notes || null,
								files: fileNames,
							},
						};
					}

					return {
						...field,
						value: rawVal,
					};
				});

				// Collect actual files from custom form fields to submit as multipart 'custom_form_files'
				const collectCustomFormFiles = (field, rawVal) => {
					const tryCollectFile = (file) => {
						if (!file) return;
						const isFileObject = (typeof File !== "undefined" && file instanceof File) || (file && typeof file === "object" && "name" in file && "size" in file);
						if (isFileObject) {
							customFormFilesToAppend.push(file);
						}
					};
					if (!rawVal) return;
					if (field.type === "attachment") {
						if (rawVal.attachmentType === "custom_form_files") {
							if (Array.isArray(rawVal.file)) {
								rawVal.file.forEach(tryCollectFile);
							} else {
								tryCollectFile(rawVal.file);
							}
						}
					} else if (field.type === "file_upload") {
						const v = rawVal;
						if (Array.isArray(v)) {
							v.forEach(tryCollectFile);
						} else {
							tryCollectFile(v);
						}
					} else if (field.type === "inspection") {
						const files = rawVal?.files || rawVal?.file;
						if (Array.isArray(files)) {
							files.forEach(tryCollectFile);
						} else {
							tryCollectFile(files);
						}
					}
				};

				fieldsSource.forEach((field) => {
					if (["attachment", "file_upload", "inspection"].includes(field?.type)) {
						const rawVal = customFormValues[field.name];
						collectCustomFormFiles(field, rawVal);
					}
				});

				customFormDataPayload = [
					{
						form_id: selectedForm?.id,
						form_version: selectedForm?.latestVersion,
						form_value: {
							title: selectedForm?.title || `Form #${selectedForm?.id}`,
							fields: fieldsWithValue,
						},
					},
				];
			}
		} else {
			const selectedTicket = tickets.find((t) => t.ticket_id === formData.ticket);
			const selectedServiceReports = Array.isArray(formData.service_reports) ? formData.service_reports : [];
			const hasCreateNewReport = selectedServiceReports.includes("new");
			const attachReportIds = selectedServiceReports
				.filter((v) => typeof v === "string" && v.startsWith("report:"))
				.map((v) => Number(String(v).split(":")[1]))
				.filter((n) => Number.isFinite(n));
			const selectedPackTemplateIds = selectedServiceReports
				.filter((v) => typeof v === "string" && v.startsWith("tpl:"))
				.map((v) => Number(String(v).split(":")[1]))
				.filter((n) => Number.isFinite(n));

			req_body = {
				start_datetime: toUtcFromSelectedTimezone(formData.start_date, formData.timeZone),
				end_datetime: toUtcFromSelectedTimezone(formData.end_date, formData.timeZone),
				type: isAgent ? "appointment" : "request",
				title: formData.title,
				notes: formData.notes,
				customer_id: selectedTicket?.ticket_user?.org_id || null,
				location_id: formData.location,
				user_id: isAgent ? selectedTicket?.ticket_user?.id : user?.id || null,
				department_id: selectedTicket?.dept_id || 1,
				staff_ids: [formData.staff_assigned],
				staff_accountable: selectedTicket?.accountable_staff_id || null,
				booking_timezone: formData.timeZone,
				createReport: hasCreateNewReport, // legacy flag; backend uses create_reports when present
				create_reports: hasCreateNewReport ? [{ report_flow: formData.report_flow || "customer_visibility", job_type: formData.job_type || "TM" }] : [],
				createTicket: false,
				ticket_id: selectedTicket?.ticket_id || formData.ticket || null,
				job_id: null,
				job_type: hasCreateNewReport ? formData.job_type : null,
				service_report_pack_id: formData.service_report_pack_id || null,
				attach_report_ids: attachReportIds,
				selected_pack_template_ids: selectedPackTemplateIds,
				service_type: selectedTicket?.service_type || null,
				priority: selectedTicket?.priority_id || null,
				due_date: selectedTicket?.due_date || null,
				equipment_id: selectedTicket?.provision_id || null,
			};
		}

		// If checklist is present, submit multipart to support custom form files
		const shouldSubmitMultipart = Boolean(formData.ticket && formData.ticket === "new" && customFormDataPayload);
		if (shouldSubmitMultipart) {
			const fd = new FormData();

			const appendScalar = (key, value) => {
				if (value === undefined || value === null) return;
				if (moment.isMoment(value)) {
					fd.append(key, value.toISOString());
					return;
				}
				fd.append(key, String(value));
			};

			Object.entries(req_body).forEach(([key, value]) => {
				// Avoid sending false-like booleans as truthy strings
				if ((key === "createReport" || key === "createTicket") && !value) return;
				if (key === "staff_ids") {
					fd.append(key, JSON.stringify(Array.isArray(value) ? value : [value]));
					return;
				}
				appendScalar(key, value);
			});

			fd.append("custom_form_data", JSON.stringify(customFormDataPayload));
			(customFormFilesToAppend || []).forEach((file) => {
				fd.append("custom_form_files", file, file.name);
			});
			payloadToSend = fd;
		} else {
			payloadToSend = req_body;
		}

		// If user selected "Other" location, pass full address to create a new location
		if (formData.location === "other") {
			if (payloadToSend instanceof FormData) {
				payloadToSend.set("location_id", "");
				payloadToSend.set("new_location", JSON.stringify({
					country: formData.country || "",
					street1: formData.street1 || "",
					street2: formData.street2 || "",
					state: formData.state || "",
					city: formData.city || "",
					zip: formData.zip || "",
					address: formData.address || "",
					site_name: formData.site_name || "",
				}));
				payloadToSend.set("isCustomerSite", isServiceManager ? String(Boolean(formData.isCustomerSite)) : "false");
			} else {
				req_body.location_id = null;
				req_body.new_location = {
					country: formData.country || "",
					street1: formData.street1 || "",
					street2: formData.street2 || "",
					state: formData.state || "",
					city: formData.city || "",
					zip: formData.zip || "",
					address: formData.address || "",
					site_name: formData.site_name || "",
					parent_site_id: formData.isCustomerSite ? formData.parent_site_id || null : null,
			};
				req_body.isCustomerSite = isServiceManager ? formData.isCustomerSite : false;
			}
		}

		if (isEditing) {
			if (payloadToSend instanceof FormData) {
				payloadToSend.append("appointment_id", String(appointmentData.id));
			} else {
				req_body.appointment_id = appointmentData.id;
			}
		}

		console.log("Form reqBody:", payloadToSend instanceof FormData ? "[multipart]" : req_body);

		setFormSubmitting(true);

		try {
			const response = isEditing
				? await updateAppointmentService(req_body)
				: await createAppointmentService(payloadToSend);
			if (response.status) {
				const appt = response.data;
				const timeZone = dataFilters?.timeZone && dataFilters.timeZone !== "system_default" ? dataFilters.timeZone : getDefaultAppointmentTimeZone();
				const event = {
					id: appt.id,
					text: appt.title,
					startDate: moment.utc(appt.start_datetime).tz(timeZone).toDate(),
					endDate: moment.utc(appt.end_datetime).tz(timeZone).toDate(),
					status: appt?.appointment_status?.state?.toLowerCase() || "scheduled",
					type: appt.type,
					staff: appt?.assigned_staff[0]?.staff_id || 1,
					staff_name: appt?.assigned_staff[0]?.name || "John Doe",
					customer: appt.customer_id,
					user: appt.user_id,
					department: appt.department_id,
					location: appt.location_id,
					booking_timezone: appt.booking_timezone,
					notes: appt.notes,
					ticket: appt.ticket_id,
				};

				if (typeof onSuccess === "function") {
					try {
						onSuccess(appt, event);
					} catch (e) {
						console.error("CreateAppointmentForm onSuccess callback error:", e);
					}
				}

				if (setParentData) {
					setParentData((prev) => {
						const existingIndex = prev.findIndex((e) => e.id === event.id);
						if (existingIndex !== -1) {
							// Update existing event
							const updated = [...prev];
							updated[existingIndex] = event;
							return updated;
						} else {
							// Add new event
							return [...prev, event];
						}
					});
				}

				// Success Alert (USING ALERT SERVICE - updateSuccess/createSuccess)
				const successAction = isEditing ? "updated" : "created";
				const successMessage = isEditing
					? `The ${getNamespace("appointment", { capitalize: false })} has been updated successfully`
					: isAgent
						? `The ${getNamespace("appointment", { capitalize: false })} has been scheduled successfully`
						: "The request has been submitted successfully";

				AlertService.success(
					successAction,
					entity,
					response.message || successMessage
				);

				// Reset form state
				setFormData({
					customer: null,
					user: null,
					location: null,
					equipment: null,
					title: "",
					notes: "",
					type: "appointment",
					timeZone: getDefaultAppointmentTimeZone(),
					staff_assigned: null,
					department: 1,
					start_date: moment(),
					end_date: moment().add(1, "hour"),
					allDay: false,
					// New location site fields
					isCustomerSite: isServiceManager ? true : false,
					site_name: "",
					parent_site_id: null,
				});
				setCustomFormValues({});
				setCustomFormErrors({});
				setTimeout(async () => {
					setFormSubmitting(false);
					setFormOpen(false);
					// Dispatch event to notify other components (e.g., TicketContent) to refresh
					// (can be suppressed for embedded flows like CreateReportForm to avoid closing parent drawers via refresh/unmount)
					if (!suppressAppointmentsUpdatedEvent) {
						window.dispatchEvent(new Event("appointments:updated"));
					}
					// navigate(`/tickets/${response.data.ticket_id}`);
					if (fetchParentData) {
						await fetchParentData();
					}
				}, 1500);
			} else {
				// API Failure (Logic Failure Toast)
				setFormLoading(false);
				setFormSubmitting(false);

				const normalizeMessage = (msg) => (typeof msg === "string" ? msg.replace(/_/g, " ") : String(msg));
				const apiErrors = Array.isArray(response.errors) ? response.errors : [];
				const cleanedErrors = apiErrors.map(normalizeMessage).filter(Boolean);
				const fallbackMessage = normalizeMessage(response.message || "Failed to submit the form. Please try again.");
				const errorMessage = cleanedErrors.length > 0 ? cleanedErrors.join(", ") : fallbackMessage;

				// Centralized Failure (Logic Failure Toast)
				AlertService.logicFailure(
					action,
					entity,
					errorMessage
				);
				setError(errorMessage);
			}
		} catch (error) {
			// System/Network Error
			setFormSubmitting(false);
			setFormLoading(false);

			// Centralized System Error Toast
			AlertService.systemError(
				`Failed to ${action} ${entity}. Network error or unexpected server response.`
			);

			const errorMessage = error.message || "An unexpected error occurred.";
			setError(errorMessage);
		}
	};

	const formButtons =
		formData.ticket && formData.ticket === "new"
			? [
				{
					label: `Back`,
					icon: null,
					onClick: () => {
						if (activeStep !== 0) {
							handleBack();
						}
					},
					variant: "contained",
				},
				{
					label: activeStep === steps.length - 1 ? `Submit` : "Next",
					icon: null,
					onClick: () => {
						if (activeStep === steps.length - 1) {
							handleSubmit();
						} else {
							handleNext();
						}
					},
					variant: "contained",
				},
			]
			: [
				{
					label: isEditing ? `Update` : `Submit`,
					icon: null,
					onClick: () => {
						handleSubmit();
					},
					variant: "contained",
				},
			];

	return (
		<>
			<LocalizationProvider dateAdapter={AdapterMoment}>
				<DrawerForm
					open={formOpen}
					setOpen={setFormOpen}
					handleClose={handleCloseForm}
					handleSubmit={handleSubmit}
					formButtons={formButtons}
					alert={error}
					isExpanded={isExpanded}
					setIsExpanded={setIsExpanded}
					isExpandedToggle={false}
					formTitle={formTitle.title}
					formSubTitle={formTitle.subtitle}>
					{formSubmitting || formLoading ? (
						<Box
							p={2}
							width="100%"
							sx={{
								...flexCol,
								justifyContent: "center",
								alignItems: "center",
								minHeight: "500px",
							}}>
							<CircularProgress />
							{formSubmitting && (
								<Typography variant="h6" mt={2}>
									{isEditing
										? `Updating ${getNamespace("appointment")}`
										: `${isAgent ? "Scheduling" : "Requesting"} New ${getNamespace("appointment")}`}
								</Typography>
							)}
						</Box>
					) : (
						<>
							{formData.ticket && formData.ticket === "new" && (
								<Stepper activeStep={activeStep} alternativeLabel>
									{steps.map((step, index) => (
										<Step key={step.label}>
											<StepLabel>
												<Typography variant="body1" fontWeight={"bold"}>
													{step.label}
													{!step.required && (
														<span
															style={{
																fontSize: "10px",
																fontStyle: "italic",
																color: "gray",
																ml: "5px",
															}}>
															- Optional
														</span>
													)}
												</Typography>
												<Typography variant="body2" fontSize={"11px"} color="text.secondary">
													{step.description}
												</Typography>
											</StepLabel>
										</Step>
									))}
								</Stepper>
							)}
							{activeStep === 0 && (
								<>
									<FormField
										type={"text"}
										label={"Title"}
										showRequired={true}
										name={"title"}
										value={formData.title}
										onChange={handleFormChange}
										error={formErrors.title}
										inputRef={textFieldRef}
										placeholder={
											isAgent
												? `Please specify the title for the ${getNamespace("appointment", { capitalize: true, plural: false })}`
												: `Please specify the reason for requesting the ${getNamespace("appointment", { capitalize: true, plural: false })}`
										}
									/>

									<Box display="flex" alignItems="flex-start">
										<Box width="200px" minWidth="200px">
											<Typography fontWeight="bold">
												Description <span style={{ color: "red" }}>*</span>
											</Typography>
										</Box>
										<Box sx={{ width: "100%" }}>
											<RichTextEditor
												ref={editorRef}
												value={formData.notes}
												onChange={handleEditorChange}
												placeholder={`Details on the reason(s) for ${isAgent ? "Scheduling" : "Request"
													} an ${getNamespace("appointment", {
														capitalize: true,
														plural: false,
													})}...`}
												error={formErrors.notes}
											/>
											{formErrors.notes && (
												<Typography color="error" variant="body1" fontSize="12px" mt={1}>
													Description is required
												</Typography>
											)}
										</Box>
									</Box>
									{formData.ticket && formData.ticket === "new" && (
										<Typography variant="body1" color="text.secondary" fontSize={"11px"}>
											<b>Note: </b> Please note that same title and description will be used as the subject and description for
											the {getNamespace("ticket")}, respectively.
										</Typography>
									)}
									<Divider flexItem />
									<Box display="flex" alignItems="center">
										<Box width="200px" minWidth="200px">
											<Typography variant="body1" fontWeight={"bold"}>
												Start Date Time <span style={{ color: "red" }}>*</span>
											</Typography>
										</Box>

										<DateTimePicker
											value={formData.start_date}
											onChange={handleDateChange("start_date")}
											viewRenderers={{
												hours: renderTimeViewClock,
												minutes: renderTimeViewClock,
												seconds: renderTimeViewClock,
											}}
											slotProps={{
												textField: {
													size: "small",
													error: formErrors?.start_date,
												},
												popper: {
													placement: "top-start",
													modifiers: [
														{
															name: "flip",
															enabled: true,
															options: {
																fallbackPlacements: ["top", "bottom"],
															},
														},
													],
												},
												desktopPaper: {
													sx: {
														maxHeight: "500px",
														overflowY: "auto",
													},
												},
											}}
											sx={{
												flex: 1,
												minWidth: 130,
												width: "100%",
											}}
										/>
									</Box>
									<Box display="flex" alignItems="center">
										<Box width="200px" minWidth="200px">
											<Typography variant="body1" fontWeight={"bold"}>
												End Date Time <span style={{ color: "red" }}>*</span>
											</Typography>
										</Box>

										<DateTimePicker
											value={formData.end_date}
											onChange={handleDateChange("end_date")}
											viewRenderers={{
												hours: renderTimeViewClock,
												minutes: renderTimeViewClock,
												seconds: renderTimeViewClock,
											}}
											slotProps={{
												textField: {
													size: "small",
													error: formErrors?.end_date,
												},
												popper: {
													placement: "top-start",
													modifiers: [
														{
															name: "flip",
															enabled: true,
															options: {
																fallbackPlacements: ["top", "bottom"],
															},
														},
													],
												},
												desktopPaper: {
													sx: {
														maxHeight: "500px",
														overflowY: "auto",
													},
												},
											}}
											sx={{
												flex: 1,
												minWidth: 130,
												width: "100%",
											}}
										/>
									</Box>
									<Divider flexItem />

									<FormField
										type="autocomplete"
										label="Time Zone"
										name="timeZone"
										value={formData.timeZone}
										error={formErrors.timeZone}
										onChange={handleFormChange}
										options={timeZoneOptions}
										showRequired={true}
									/>
									{!isEditing && (
										<>
											<Divider flexItem>
												<b>
													{getNamespace("appointment", { capitalize: true, plural: false })} References <span style={{ color: "red" }}>*</span>
												</b>
											</Divider>
											<FormField
												type="autocomplete"
												label={getNamespace("ticket", { capitalize: true })}
												name="ticket"
												value={formData.ticket}
												error={formErrors.ticket}
												onChange={handleFormChange}
												options={ticketOptions}
												showRequired={true}
												disabled={isEditing ? true : (lockPrefilledTicket && isPrefilled)}
											/>
