	};

	const handleOverrideApproval = (report) => {
		setReviewInitialCustomerEditable(true);
		setSelectedReportWorkLog(report?.report?.report_id || report?.id);
		setViewReportFormOpen(true);
	};

	const handleWithdrawReport = async (row) => {
		const reportId = row?.report?.report_id || row?.id;
		if (!reportId) return;

		const result = await Swal.fire({
			icon: "warning",
			title: `Warning`,
			text: `You are attempting to Withdraw a Submitted ${nsReport}, This action will move the ${nsReport} back to In Progress Status.`,
			showDenyButton: true,
			confirmButtonText: "Yes, Withdraw",
			denyButtonText: "Cancel",
		});

		if (!result.isConfirmed) return;

		try {
			const payload = {
				report_id: reportId,
				status: "in_progress",
				withdraw: true,
				withdraw_date: new Date(),
			};
			const response = await updateStatusReport(payload);
			if (response?.status) {
				toast.fire({ message: `${nsReport} withdrawn successfully`, severity: "success", duration: 2000 });
				await fetchServiceReports();
				// reflect update in any open drawers
				window.dispatchEvent(new Event("service_reports:updated"));
			} else {
				toast.fire({ message: `Failed to withdraw ${nsReport}`, severity: "error" });
			}
		} catch (err) {
			console.error("Withdraw error", err);
			toast.fire({ message: `Failed to withdraw ${nsReport}`, severity: "error" });
		}
	};

	const handleCloseReport = async (row) => {
		const reportId = row?.report?.report_id || row?.id;
		if (!reportId) return;

		const result = await Swal.fire({
