			showDenyButton: true,
			confirmButtonText: "Yes, Close",
			denyButtonText: "Cancel",
		});

		if (!result.isConfirmed) return;

		try {
			const payload = {
				report_id: reportId,
				status: "closed",
			};
			const response = await updateStatusReport(payload);
			if (response?.status) {
				toast.fire({ message: `${nsReport} closed successfully`, severity: "success", duration: 2000 });
				await fetchServiceReports();
				window.dispatchEvent(new Event("service_reports:updated"));
			} else {
				toast.fire({ message: response?.message || `Failed to close ${nsReport}`, severity: "error" });
			}
		} catch (err) {
			console.error("Close report error", err);
			toast.fire({ message: `Failed to close ${nsReport}`, severity: "error" });
		}
	};

	const handleGenerateInvoice = async () => {
