			});
			return;
		}

		setInvoiceFormOpen(true);
	};

	const handleSendReport = async (row) => {
		const reportId = row.report?.report_id || row.id;
		const entity = getNamespace("service_report", { capitalize: true, plural: false });

		setSendEmailLoading((prev) => ({ ...prev, [row.id]: true }));
