export const getIsTicketParticipant = ({
	isAgent,
	isTicketCollaborator,
	isAssignee,
	isAccountable,
	isOwner,
	ticketDeptId,
	userDepartments,
}) => {
	const hasExplicitTicketDeptAccess = (() => {
		if (!Boolean(isAgent)) return false;
		if (ticketDeptId === undefined || ticketDeptId === null) return false;

		const deptId = Number(ticketDeptId);
		if (Number.isNaN(deptId)) return false;

		const depts = Array.isArray(userDepartments) ? userDepartments : [];
		return depts.some((d) => {
			const candidate = d?.department?.id ?? d?.dept_id ?? d?.id ?? null;
			return Number(candidate) === deptId;
		});
	})();

	return (
		Boolean(isAgent) &&
		Boolean(isTicketCollaborator) &&
		!Boolean(isAssignee) &&
		!Boolean(isAccountable) &&
		!Boolean(isOwner) &&
		!hasExplicitTicketDeptAccess
	);
};

export const getIsTicketParticipantForTicketRecord = ({
	ticket,
	isAgent,
	staffId,
	userDepartments,
}) => {
	if (!ticket || !isAgent || !staffId) return false;

	const normalizedStaffId = String(staffId);
	const isTicketCollaborator = (ticket?.ticket_collaborators || []).some(
		(collab) =>
			String(collab?.staff_id ?? collab?.collaborator_staff?.staff_id ?? "") === normalizedStaffId
	);
	const isAssignee =
		String(ticket?.assigned_staff_id ?? ticket?.ticket_assignee?.staff_id ?? "") === normalizedStaffId;
	const isAccountable =
		String(ticket?.accountable_staff_id ?? ticket?.ticket_accountable?.staff_id ?? "") === normalizedStaffId;
	const isOwner =
		String(ticket?.created_by_staff_id ?? ticket?.ticket_creator_staff?.staff_id ?? "") === normalizedStaffId;

	return getIsTicketParticipant({
		isAgent,
		isTicketCollaborator,
		isAssignee,
		isAccountable,
		isOwner,
		ticketDeptId: ticket?.dept_id,
		userDepartments,
	});
};

utilities.customFormValidation.js:
// Shared custom form validation utilities

// Validate fields for a set of forms against edited values
// Expected shapes:
// - forms: array of { schema: { fields: [...] } } or { form_value: { fields: [...] } }
// - editedValues: { [formId]: { [fieldKey]: value } } OR flat { [fieldKey]: value } depending on caller

export const isFieldVisible = (field, userMode = 'agent') => {
  const cfg = field.configuration || {};
  return userMode === 'agent'
    ? (cfg.visibleAgents !== false && cfg.visibleAgents !== 'false' && cfg.visibleAgents !== 0)
    : (cfg.visibleEndUsers !== false && cfg.visibleEndUsers !== 'false' && cfg.visibleEndUsers !== 0);
};

export const isFieldEditable = (field, userMode = 'agent') => {
  const cfg = field.configuration || {};
  return userMode === 'agent'
    ? (cfg.editableAgents === true || cfg.editableAgents === 'true' || cfg.editableAgents === 1)
    : (cfg.editableEndUsers === true || cfg.editableEndUsers === 'true' || cfg.editableEndUsers === 1);
};

const getRichTextPlainText = (value) => {
  if (!value) return "";
  const html = typeof value === "string" ? value : (value?.html || "");
  if (!html) return "";

  // Image-only or link-only rich text should satisfy required validation
  // (textContent can be empty even though content is meaningful).
  if (/<\s*img\b/i.test(html)) return "[image]";
  if (/<\s*a\b[^>]*\bhref\s*=/i.test(html)) return "[link]";

  // Strip tags + normalize whitespace; treat &nbsp; as space
  return html
    .replace(/<script[\s\S]*?>[\s\S]*?<\/script>/gi, " ")
    .replace(/<style[\s\S]*?>[\s\S]*?<\/style>/gi, " ")
    .replace(/<[^>]+>/g, " ")
    .replace(/&nbsp;/gi, " ")
    .replace(/\s+/g, " ")
    .trim();
};

export const validateCustomFormFields = (forms, editedValues, options = {}) => {
  const errors = {};
  const userMode = options.userMode || 'agent';

  if (!Array.isArray(forms)) return errors;

  // Determine whether editedValues is keyed by form id or flat
  const isPerForm = !!forms.find((f) => editedValues && editedValues[(f.form_id || f.id)]);

  forms.forEach((form) => {
    const formId = form.form_id || form.id;
    const fields = form.schema?.fields || form.form_value?.fields || [];
    const valuesForForm = isPerForm ? (editedValues?.[formId] || {}) : (editedValues || {});

    fields.forEach((field) => {
      if (!field) return;
      const fieldKey = field.name || field.id;
      if (!fieldKey) return;

      const rawVal = valuesForForm[fieldKey] !== undefined ? valuesForForm[fieldKey] : (field.value || field.defaultValue || null);

      // Determine required and visible based on configuration and user mode
      const cfg = field.configuration || {};

      // If field is not visible, skip validation
      if (!isFieldVisible(field, userMode)) return;

      const isRequired = userMode === 'agent'
        ? (cfg.requiredAgents === true || cfg.requiredAgents === 'true' || cfg.requiredAgents === 1)
        : (cfg.requiredEndUsers === true || cfg.requiredEndUsers === 'true' || cfg.requiredEndUsers === 1);

      // Validation rules per type
      switch (field.type) {
        case 'inspection': {
          const inspection = (rawVal && typeof rawVal === 'object') ? rawVal.inspection : rawVal;
          const notes = (rawVal && typeof rawVal === 'object') ? (rawVal.notes || '') : '';
          const files = (rawVal && typeof rawVal === 'object') ? (rawVal.files || rawVal.file || []) : [];

          // Normalize and detect flag/fail
          const norm = ((inspection ?? '') + '').trim().toLowerCase();
          const isFlagOrFail = norm === 'flag' || norm === 'fail' || norm === '2' || norm === '0';
          const isEmpty = inspection === undefined || inspection === null || String(inspection).trim() === '';

          const fieldErr = {};

          if (isRequired && isEmpty) {
            errors[fieldKey] = 'Inspection result is required';
          } else if (isFlagOrFail) {
            if (!notes || !String(notes).trim()) {
              fieldErr.notes = 'Notes are mandatory for Flag and Fail inspections';
            }
            const hasFiles = Array.isArray(files) ? files.length > 0 : Boolean(files);
            if (!hasFiles) {
              fieldErr.files = `Files is mandatory for Flag and Fail inspections`;
            }
            if (Object.keys(fieldErr).length > 0) {
              errors[fieldKey] = fieldErr;
            }
          }
          break;
        }
        case 'attachment': {
          if (!isRequired) break;
          const v = rawVal || {};
          const attType = v.attachmentType || 'na';
          if (attType === 'url') {
            if (!v.attachmentUrl || String(v.attachmentUrl).trim() === '') {
              errors[fieldKey] = 'Attachment URL is required';
            }
          } else if (attType === 'custom_form_files') {
            const file = v.file;
            const hasFile = Array.isArray(file) ? file.length > 0 : Boolean(file);
            if (!hasFile) {
              errors[fieldKey] = 'Attachment file is required';
            }
          } else {
            // attType === 'na'
            errors[fieldKey] = 'Attachment is required';
          }
          break;
        }
        case 'file_upload': {
          if (!isRequired) break;
          const v = rawVal;
          const hasFile = Array.isArray(v) ? v.length > 0 : Boolean(v);
          if (!hasFile) {
            errors[fieldKey] = 'File is required';
          }
          break;
        }
        case 'choices_dropdown_multiple':
        case 'choices_checkbox_multiple': {
          if (!isRequired) break;
          const v = rawVal;
          if (!Array.isArray(v) || v.length === 0) {
            errors[fieldKey] = 'Please select at least one option';
          }
          break;
        }
        case 'integer':
        case 'number': {
          const v = rawVal;
          const isEmpty = v === undefined || v === null || (typeof v === 'string' && v.trim() === '') || (Array.isArray(v) && v.length === 0);

          if (isRequired && isEmpty) {
            errors[fieldKey] = 'This field is required';
          } else if (!isEmpty) {
            const numVal = Number(v);
            if (isNaN(numVal)) {
              errors[fieldKey] = 'Please enter a valid number';
            } else {
              const min = cfg.minValue;
              const max = cfg.maxValue;
              if (min !== undefined && min !== null && min !== "" && numVal < Number(min)) {
                errors[fieldKey] = `Value cannot be less than ${min}`;
              }
              if (max !== undefined && max !== null && max !== "" && numVal > Number(max)) {
                errors[fieldKey] = `Value cannot be greater than ${max}`;
              }
            }
          }
          break;
        }
        case 'choices_dropdown':
        case 'choices_radio':
        case 'user_dropdown':
        case 'grouped_user_dropdown':
        case 'email':
        case 'text':
        case 'textarea':
        case 'rich_text':
        case 'date_picker':
        case 'datetime_picker': {
          if (!isRequired) break;
          const v = rawVal;
          const isEmpty = field.type === "rich_text"
            ? getRichTextPlainText(v) === ""
            : (v === undefined || v === null || (typeof v === 'string' && v.trim() === '') || (Array.isArray(v) && v.length === 0));
          if (isEmpty) {
            errors[fieldKey] = 'This field is required';
          }
          break;
        }
        default:
          // Add more field-type validations here as needed
          break;
      }
    });
  });

  return errors;
};

