utilities.service_reportUtils.js:
const { models, sequelize } = require("../models");
const { getAllowedDeptIds, getStaffInvolvedTicketIds } = require("./ticketUtil");
const { Op } = require("sequelize");

const fetchReportsHelper = async (where = {}, single = false, staffId = null) => {
	let finalWhere = where;

	if (staffId) {
		const allowedDeptIds = await getAllowedDeptIds(staffId, 'service_report_management.service_report.view');
		const involvedTicketIds = await getStaffInvolvedTicketIds(staffId);

		// Staff must have the module view permission in at least one department.
		// Collaboration expands scope to involved tickets, but does not grant the module permission itself.
		if (!allowedDeptIds || allowedDeptIds.length === 0) {
			return single ? null : [];
		}

		const scopeOr = [
			{ '$ticket.dept_id$': { [Op.in]: allowedDeptIds } },
			...(involvedTicketIds && involvedTicketIds.length > 0
				? [{ '$ticket.ticket_id$': { [Op.in]: involvedTicketIds } }]
				: []),
		];

		const scopeWhere = { [Op.or]: scopeOr };
		finalWhere =
			!where || Object.keys(where).length === 0
				? scopeWhere
				: { [Op.and]: [where, scopeWhere] };
	}

	const includes = [
		{
			model: models.service_report_lines,
			as: "lines", // association alias per associations file
			required: false,
			separate: true,
			order: [
				[{ model: models.items, as: "item" }, "name", "ASC"],
				[{ model: models.staff, as: "staff" }, "name", "ASC"],
			],
			include: [
				{
					model: models.items,
					as: "item", // service_report_items -> items uses alias "item"
					required: false,
					include: [
						{
							model: models.item_types,
							as: "item_type",
							required: false,
						},
					],
				},
				{
					model: models.staff,
					as: "staff", // quote_items -> staff (if exists)
					required: false,
					include: [
						{
							model: models.staff_billing_profile,
							as: "billing_profiles",
							required: false,
							separate: true,
							include: [
								{
									model: models.billing_profile,
									as: "billing_profile",
									attributes: ["id", "name", "rate", "cost", "currency", "unit"],
									required: false,
								},
							],
						},
					],
				},
				{
					model: models.service_report_work_logs,
					as: "work_logs",
					required: false,
					separate: true,

					include: [
						{
							model: models.staff,
							as: "staff", // quote_items -> staff (if exists)
							required: false,
							include: [
								{
									model: models.staff_billing_profile,
									as: "billing_profiles",
									required: false,
									separate: true,
									include: [
										{
											model: models.billing_profile,
											as: "billing_profile",
											attributes: ["id", "name", "rate", "cost", "currency", "unit"],
											required: false,
										},
									],
								},
							],
						},
					],
				},
			],
		},
		{
			model: models.service_report_collaborators,
			as: "collaborators",
			required: false,
			separate: true,
			include: [
				{
					model: models.staff,
					as: "staff",
					include: [
						{
							model: models.staff_billing_profile,
							as: "billing_profiles",
							required: false,
							separate: true,
							include: [
								{
									model: models.billing_profile,
									as: "billing_profile",
									attributes: ["id", "name", "rate", "cost", "currency", "unit"],
									required: false,
								},
							],
						},
					],
				}
			],
		},
		{
			model: models.quote_header,
			as: "quote",
		},
		{
			model: models.ticket,
			as: "ticket",
			required: false,
			include: [
				{ model: models.ticket_status, as: "ticket_status" },
				{
					model: models.organization_equipments,
					as: "ticket_equipment",
					include: [{ model: models.organization_sites }],
				},
				{
					model: models.user,
					as: "ticket_user",
					include: [
						{
							model: models.organization,
							as: "organization",
						},
					],
				},
			],
		},
		{
			model: models.appointment,
			as: "appointment",
			required: false,
		},
		{
			model: models.staff,
			as: "service_report_creator", // quote_items -> staff (if exists)
			required: false,
		},
		{
			model: models.staff,
			as: "service_report_override_staff", // quote_items -> staff (if exists)
			required: false,
		},
		{
			model: models.staff,
			as: "service_report_closer",
			required: false,
		},
	];
	let reports = single ? null : [];
	if (single) {
		reports = await models.service_report_header.findOne({ where: finalWhere, include: includes });
	} else {
		reports = await models.service_report_header.findAll({ where: finalWhere, include: includes });
	}

	const applyUnitBreakdowns = async (report) => {
		const lines = report?.lines || [];
		const reportType = report?.report_type || report?.report?.report_type;
		// Prefetch billing profile units for planned breakdown inference (quote-derived planned values).
		const bpIds = Array.from(
			new Set(
				(lines || [])
					.map((l) => l?.staff_bp_id)
					.filter((id) => id !== null && id !== undefined && id !== "")
					.map((id) => Number(id))
					.filter((id) => Number.isFinite(id))
			)
		);
		const bpUnitMap = new Map();
		if (bpIds.length > 0) {
			const bps = await models.billing_profile.findAll({
				where: { id: bpIds },
				attributes: ["id", "unit"],
			});
			bps.forEach((bp) => bpUnitMap.set(Number(bp.id), String(bp.unit || "hr").toLowerCase()));
		}
		for (const line of lines) {
			const logs = line?.work_logs || [];
			let actualQtyHr = 0;
			let actualQtyDay = 0;
			let actualDurHr = 0;
			let actualDurDay = 0;

			for (const wl of logs) {
				const value = Number(wl?.log_value) || 0;
				const unit = String(wl?.log_unit || "hr").toLowerCase() === "day" ? "day" : "hr";

				if (reportType === "TM") {
					if (unit === "day") actualQtyDay += value;
					else actualQtyHr += value;
				} else if (reportType === "FFM") {
					if ([2, 3].includes(line?.item_type_id)) {
						if (unit === "day") actualQtyDay += value;
						else actualQtyHr += value;
					} else {
						if (unit === "day") actualDurDay += value;
						else actualDurHr += value;
					}
				} else {
					// Fallback: treat as duration-like.
					if (unit === "day") actualDurDay += value;
					else actualDurHr += value;
				}
			}

			const plannedQtyHr = Number(line?.planned_quantity) || 0;
			const plannedDurHr = Number(line?.planned_duration) || 0;

			const lineUnit = String(line?.item_unit || "hr").toLowerCase();
			const bpUnit = bpUnitMap.get(Number(line?.staff_bp_id)) || "hr";
			const plannedQtyBreakdown =
				reportType === "TM" && line?.staff_id
					? (lineUnit === "day" || bpUnit === "day" ? { hr: 0, day: plannedQtyHr } : { hr: plannedQtyHr, day: 0 })
					: { hr: plannedQtyHr, day: 0 };
			if (reportType === "TM" && !line?.staff_id) {
				// Non-staff TM lines are item/material quantities; do not represent them as hr/day.
				line.setDataValue("planned_quantity_breakdown", null);
			} else {
				line.setDataValue("planned_quantity_breakdown", plannedQtyBreakdown);
			}

			const plannedDurUnit = String(line?.planned_duration_unit || "hr").toLowerCase();
			const plannedDurBreakdown =
				plannedDurUnit === "day" ? { hr: 0, day: plannedDurHr } : { hr: plannedDurHr, day: 0 };
			line.setDataValue("planned_duration_breakdown", plannedDurBreakdown);
			if (reportType === "TM" && !line?.staff_id) {
				line.setDataValue("actual_quantity_breakdown", null);
			} else {
				line.setDataValue("actual_quantity_breakdown", { hr: actualQtyHr, day: actualQtyDay });
			}
			line.setDataValue("actual_duration_breakdown", { hr: actualDurHr, day: actualDurDay });
		}
	};

	if (single) {
		if (reports) await applyUnitBreakdowns(reports);
	} else {
		for (const r of reports || []) {
			// eslint-disable-next-line no-await-in-loop
			await applyUnitBreakdowns(r);
		}
	}

	return reports;
};

module.exports = { fetchReportsHelper };

utilities.ticketAccessUtil.js:
const { models } = require("../models");
const { getAllowedDeptIds, isStaffManagerOrAdmin } = require("./ticketUtil");
const { getCustomerVisibleUserIds } = require("../services/customer_site_access.service");

const createTicketAccessChecker = async (req) => {
	if (!req?.user) {
		return async () => false;
	}

	// Staff access rules
	if (req.user.staff_id) {
		const staffId = req.user.staff_id;

		const collabTickets = await models.ticket_collaborators.findAll({
			where: { staff_id: staffId },
			attributes: ["ticket_id"],
			raw: true,
		});
		const collabTicketIds = new Set(collabTickets.map((c) => Number(c.ticket_id)));

		const allowedDeptIds = await getAllowedDeptIds(staffId, "ticket_management.ticket.view");
		const allowedDeptIdSet = new Set((allowedDeptIds || []).map((d) => Number(d)));

		const isManagerOrAdmin = await isStaffManagerOrAdmin(staffId);

		return async (ticketData) => {
			if (!ticketData) return false;
			const ticketId = Number(ticketData.ticket_id ?? ticketData.id);

			if (Number(ticketData.accountable_staff_id) === Number(staffId)) return true;
			if (Number(ticketData.assigned_staff_id) === Number(staffId)) return true;
			if (Number(ticketData.created_by_staff_id) === Number(staffId)) return true;
			if (collabTicketIds.has(ticketId)) return true;

			if (isManagerOrAdmin && allowedDeptIdSet.has(Number(ticketData.dept_id))) return true;

			return false;
		};
	}

	// Customer/end-user access rules
	if (req.user.user_id) {
		const userId = req.user.user_id;

		// Use central "customer visible users" logic so ticket visibility stays consistent
		// across org-wide vs child-site visibility settings.
		const visibleUserIds = await getCustomerVisibleUserIds(userId);
		const visibleUserIdSet = new Set((visibleUserIds || []).map((id) => Number(id)));

		return async (ticketData) => {
			if (!ticketData) return false;
			const ticketOwnerUserId = Number(ticketData.user_id);
			if (Number(ticketOwnerUserId) === Number(userId)) return true;
			if (visibleUserIdSet.has(ticketOwnerUserId)) return true;
			return false;
		};
	}

	return async () => false;
};

const checkTicketAccess = async (ticketData, req) => {
	const canAccess = await createTicketAccessChecker(req);
	return canAccess(ticketData);
};

module.exports = {
	createTicketAccessChecker,
	checkTicketAccess,
};

