const { Sequelize, Op } = require("sequelize");
module.exports = (sequelize, DataTypes) => {
    return form_schema.init(sequelize, DataTypes);
};

class form_schema extends Sequelize.Model {
    static init(sequelize, DataTypes) {
        return super.init(
			{
				id: {
					autoIncrement: true,
					type: DataTypes.INTEGER,
					allowNull: false,
					primaryKey: true,
				},
				name: {
					type: DataTypes.STRING(255),
					allowNull: false,
				},
				title: {
					type: DataTypes.STRING(255),
					allowNull: false,
				},
				description: {
					type: DataTypes.TEXT,
					allowNull: true,
				},
				schema: {
					type: DataTypes.JSON,
					allowNull: true,
					defaultValue: {},
				},
				latestVersion: {
					type: DataTypes.INTEGER,
					allowNull: false,
				},
				service_type_id: {
					type: DataTypes.INTEGER,
					allowNull: true,
				},
 				eq_id: {
 					type: DataTypes.INTEGER,
 					allowNull: true,
 				},
				all_equipments: {
					type: DataTypes.BOOLEAN,
					allowNull: false,
					defaultValue: false,
				},
 				formFor: {
 					type: DataTypes.STRING(50),
 					allowNull: true,
 					defaultValue: "TICKET",
 				},
				all_provisions: {
					type: DataTypes.BOOLEAN,
					allowNull: false,
					defaultValue: false,
				},
				isActive: {
					type: DataTypes.BOOLEAN,
					defaultValue: true,
				},
				isDefault: {
					type: DataTypes.BOOLEAN,
					defaultValue: false,
					allowNull: false,
				},
				createdBy: {
					type: DataTypes.INTEGER,
					allowNull: false,
				},
				updatedBy: {
					type: DataTypes.INTEGER,
					allowNull: false,
				},
			},
			{
				sequelize,
				tableName: "form_schema",
				timestamps: true,
				paranoid: true,
				indexes: [
					{
						name: "FORM_SCHEMA_PRIMARY",
						unique: true,
						using: "BTREE",
						fields: [{ name: "id" }],
					},
					{
						name: "service_equipment_index",
						using: "BTREE",
						fields: [{ name: "service_type_id" }, { name: "eq_id" }],
					},
					{
						name: "eq_index",
						using: "BTREE",
						fields: [{ name: "eq_id" }],
					},
				],
				hooks: {
					beforeSave: async (form) => {
						if (form.isDefault && (form.formFor === "TICKET" || !form.formFor)) {
							// Remove default flag from other forms for same service+equipment
							await form_schema.update(
								{ isDefault: false },
								{
									where: {
										service_type_id: form.service_type_id,
										eq_id: form.eq_id,
										id: { [Op.ne]: form.id }, // exclude current form
									},
								}
							);
						}
					},
				},
			}
		);
    }
}

