const Sequelize = require("sequelize");
module.exports = (sequelize, DataTypes) => {
	return staff.init(sequelize, DataTypes);
};

class staff extends Sequelize.Model {
	static init(sequelize, DataTypes) {
		return super.init(
			{
				staff_id: {
					autoIncrement: true,
					type: DataTypes.INTEGER,
					allowNull: false,
					primaryKey: true,
				},
				firstname: {
					type: DataTypes.STRING(32),
					allowNull: false,
				},
				lastname: {
					type: DataTypes.STRING(32),
					allowNull: false,
				},
				name: {
					type: DataTypes.STRING(128),
					allowNull: true,
					validate: {
						notEmpty: true,
					},
				},
				role_id: {
					type: DataTypes.INTEGER,
					allowNull: false,
				},
				phone: {
					type: DataTypes.STRING(24),
					allowNull: false,
					defaultValue: "",
					validate: {
						len: [7, 24],
						is: {
							args: /^[0-9+\-\s()]+$/,
							msg: "Phone number can only contain digits, spaces, +, -, and ()",
						},
					},
				},
				phone_ext: {
					type: DataTypes.STRING(6),
					allowNull: true,
				},
				mobile: {
					type: DataTypes.STRING(24),
					allowNull: true,
					defaultValue: null,
					validate: {
						isValidMobile(value) {
							if (value && value.trim() !== "") {
								// Check length
								if (value.length < 7 || value.length > 24) {
									throw new Error("Mobile number must be between 10 and 15 characters");
								}
								// Check format
								if (!/^[0-9+\-\s()]+$/.test(value)) {
									throw new Error("Mobile number can only contain digits, spaces, +, -, and ()");
								}
							}
						},
					},
				},
				signature: {
					type: DataTypes.TEXT,
					allowNull: true,
				},
				assigned_only: {
					type: DataTypes.BOOLEAN,
					allowNull: false,
					defaultValue: false,
				},
				show_assigned_tickets: {
					type: DataTypes.BOOLEAN,
					allowNull: false,
					defaultValue: false,
				},
				max_page_size: {
					type: DataTypes.INTEGER,
					allowNull: false,
					defaultValue: 0,
				},
				auto_refresh_rate: {
					type: DataTypes.INTEGER,
					allowNull: false,
					defaultValue: 0,
				},
				default_signature_type: {
					type: DataTypes.ENUM("none", "mine", "dept"),
					allowNull: false,
					defaultValue: "none",
				},
				default_paper_size: {
					type: DataTypes.ENUM("Letter", "Legal", "Ledger", "A4", "A3"),
					allowNull: false,
					defaultValue: "Letter",
				},
				erp_id: {
					type: DataTypes.STRING(100),
					allowNull: true,
				},
				eula_status: {
					type: DataTypes.BOOLEAN,
					allowNull: true,
					defaultValue: false,
				},
				billing_profile: {
					type: DataTypes.INTEGER,
					allowNull: true,
				},
			},
			{
				sequelize,
				tableName: "staff",
				timestamps: true,
				paranoid: true,
				deactivation: {
					enabled: true,            	// set false to disable deactivation for this model
					field: null,        		// deactivation field
					relatedModel: "staff_account",
					relatedField: "status",
					validators: [             // keys used by deactivationValidator
						"staff_open_tickets",
						"staff_pending_appointments",
						"staff_managed_departments",
						"staff_managed_organizations",
						"staff_open_tasks",
						"staff_pending_invoices",
						"staff_pending_quotes",
						"staff_pending_service_reports",
						"staff_active_schedules",
					]
				},
				indexes: [
					{
						name: "staff_PRIMARY",
						unique: true,
						using: "BTREE",
						fields: [{ name: "staff_id" }],
					},
				],
				hooks: {
					beforeValidate: (staff) => {
						if (staff.name) {
							staff.name = staff.name.trim();
						}
					},
					beforeCreate: (staff) => {
						if (staff.firstname) {
							staff.firstname = staff.firstname.trim();
							if ((staff.firstname).length === 0) {
								throw new Error("First name cannot be empty");
							}
						}
						if (staff.lastname) {
							staff.lastname = staff.lastname.trim();
							if ((staff.lastname).length === 0) {
								throw new Error("Last name cannot be empty");
							}
						}
						if (!staff.name) {
							staff.name = `${staff.firstname || ""} ${staff.lastname || ""}`.trim();
						}
					},
				},
			}
		);
	}
}

