const Sequelize = require("sequelize");
module.exports = (sequelize, DataTypes) => {
	return config.init(sequelize, DataTypes);
};

class config extends Sequelize.Model {
	static init(sequelize, DataTypes) {
		return super.init(
			{
				id: {
					autoIncrement: true,
					type: DataTypes.INTEGER,
					allowNull: false,
					primaryKey: true,
				},
				namespace: {
					type: DataTypes.STRING(64),
					allowNull: false,
				},
				key: {
					type: DataTypes.STRING(64),
					allowNull: false,
				},
				value: {
					type: DataTypes.TEXT,
					allowNull: false,
				},
			},
			{
				sequelize,
				tableName: "options",
				timestamps: true,
				paranoid: true,
				indexes: [
					{
						name: "OPTIONS_PRIMARY",
						unique: true,
						using: "BTREE",
						fields: [{ name: "id" }],
					},
					{
						name: "namespace",
